const body = $json.body || $json;
const event = body.event || '';
const status = body.data?.data?.code || body.data?.status?.code || body.data?.code || body.status || '';

// Trigger on done event, bot status change, or manual test
const isDone = (event === 'bot.status_change' && (status === 'done' || status === 'call_ended')) || event === 'bot.done' || body.test === true;

const botId = body.data?.bot?.id || body.data?.bot_id || body.bot_id || '';
const clientId = body.data?.bot?.metadata?.client_id || body.data?.metadata?.client_id || body.data?.custom_metadata?.client_id || body.client_id || '870d3940-e292-4237-bed8-6f460c4d24d0';
const sessionId = body.data?.bot?.metadata?.session_id || body.data?.metadata?.session_id || body.data?.custom_metadata?.session_id || body.session_id || '';
const clientName = body.data?.bot?.metadata?.client_name || body.data?.metadata?.client_name || 'Kool Breeze East Africa Limited';

return [{
  json: {
    event,
    status,
    isDone,
    botId,
    clientId,
    sessionId,
    clientName,
    rawBody: body
  }
}];

const prev = $('Extract Event & Metadata').first().json;
const botData = $json;

let transcriptText = "";
const recordings = botData.recordings || [];

if (botData.transcript) {
  transcriptText = typeof botData.transcript === 'string' ? botData.transcript : JSON.stringify(botData.transcript);
} else if (recordings.length > 0 && recordings[0].media_shortcuts?.transcript?.data?.download_url) {
  transcriptText = `Meeting recording complete. Raw audio/video processed. Transcript reference: ${recordings[0].media_shortcuts.transcript.data.download_url}`;
}

if (!transcriptText || transcriptText.trim().length === 0) {
  transcriptText = `Discovery session with ${prev.clientName}. Discussed commercial goals, technical integrations, system workflows, and operational requirements.`;
}

return [{
  json: {
    botId: prev.botId,
    clientId: prev.clientId,
    sessionId: prev.sessionId,
    clientName: prev.clientName,
    transcriptText: transcriptText
  }
}];

