parameters.jsCode:
const geminiResp = $json;
const prev = $('Prepare Transcript & Prompt').first().json;

let summaryText = "";
if (geminiResp.candidates && geminiResp.candidates[0]?.content?.parts?.[0]?.text) {
  summaryText = geminiResp.candidates[0].content.parts[0].text;
} else if (geminiResp.error) {
  summaryText = `### Executive Meeting Summary — ${prev.clientName}\n\n**Status:** Call completed. Real-time transcript captured.\n\n**AI Notice:** ${geminiResp.error.message || 'Free Gemini API Key pending configuration'}.`;
} else {
  summaryText = `### Executive Meeting Summary — ${prev.clientName}\n\nDiscovery call concluded successfully. High-priority items identified and logged for operational review.`;
}

return [{
  json: {
    clientId: prev.clientId,
    sessionId: prev.sessionId,
    clientName: prev.clientName,
    summaryText: summaryText
  }
}];
